const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-105.503, 35.759]);
  const aoi = point.buffer(5000); // 5km buffer around Hermit Park

  const date1 = '2022-04-19';
  const date2 = '2022-04-23';

  // 2. Cloud masking function for Landsat
  function maskL8sr(image) {
    const cloudShadowBitMask = 1 << 3;
    const cloudsBitMask = 1 << 5;
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Data Acquisition - Try Landsat 8/9
  function getLandsatCollection(startDate, endDate) {
    const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(aoi)
      .map(maskL8sr);

    const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(aoi)
      .map(maskL8sr);

    return l8.merge(l9);
  }

  // Get collections for both dates (3-day window for each)
  const col1 = getLandsatCollection('2022-04-18', '2022-04-20');
  const col2 = getLandsatCollection('2022-04-22', '2022-04-24');

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`April 19 Images: ${size1}, April 23 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Get median composites and calculate NBR
  function calculateNBR(image) {
    const nbr = image.normalizedDifference(['SR_B5', 'SR_B7']).rename('NBR');
    return image.addBands(nbr);
  }

  const img1 = calculateNBR(col1.median());
  const img2 = calculateNBR(col2.median());

  // 5. Calculate dNBR (difference in NBR)
  const dnbr = img1.select('NBR').subtract(img2.select('NBR')).rename('dNBR');

  // 6. Count burn pixels (dNBR > 0.1 indicates burn)
  const burnThreshold = 0.1;
  const burnMask = dnbr.gt(burnThreshold);

  // Count pixels in each category
  const stats = burnMask.reduceRegion({
    reducer: ee.Reducer.frequencyHistogram(),
    geometry: aoi,
    scale: 30,
    maxPixels: 1e9
  });

  const hist = stats.get('dNBR').getInfo();
  const burnPixels = hist && hist['1'] ? hist['1'] : 0;
  const nonBurnPixels = hist && hist['0'] ? hist['0'] : 0;
  const totalPixels = burnPixels + nonBurnPixels;

  console.log(`Burn pixels: ${burnPixels}, Non-burn: ${nonBurnPixels}, Total: ${totalPixels}`);

  if (totalPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 7. Calculate burn area percentage
  const burnPercent = (burnPixels / totalPixels) * 100;
  console.log(`Burn area: ${burnPercent.toFixed(2)}%`);

  // 8. Determine if burn scar increased (any burn pixels detected)
  if (burnPixels > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
